style.css:
@-moz-document domain("discord.com") {
/* Full app background */
  html, body, .appMount-2yBXZl, .app-2CXKsg, .bg-1QIAus {
    background-color: #fffafa !important;
    color: #222 !important;
  }

  /* Sidebar and servers */
  .sidebar-1tnWFu, .guilds-2JjMmN, .wrapper-1_HaEi {
    background-color: #ffe6f2 !important;
    border-right: 1px solid #fcbfd6 !important;
  }

  /* Main chat content */
  .chatContent-3KubbW, .content-1jQy2l, .container-2o3qEW, .title-31SJ6t, .scrollableContainer-15eg7h {
    background-color: #FADADD !important;
    color: #000 !important;
    border-radius: 12px !important;
    padding: 8px !important;
  }

  /* Message input area */
  .channelTextArea-1FufC0, .form-3gdLxP, .textArea-2Spzkt {
    background-color: #fffafa !important;
    border: 1px solid #fcbfd6 !important;
    border-radius: 10px !important;
    color: #333 !important;
  }

  /* Header bar and top nav */
  .titleBar-AC4pGV, .header-2o-2hj, .toolbar-3_r2xA {
    background-color: #ffe6f2 !important;
    color: #111 !important;
    border-bottom: 1px solid #fcbfd6 !important;
  }

  /* Buttons */
  .button-38aScr, .button-ejjZWC, .lookFilled-1Gx00P {
    background-color: #ffb6c1 !important;
    color: #fff !important;
    border-radius: 10px !important;
    border: none !important;
  }

  .button-38aScr:hover, .lookFilled-1Gx00P:hover {
    background-color: #ff5e95 !important;
  }

  /* Avatars rounded + borders */
  .avatar-2e8lTP, .avatar-3uk_u9 {
    border-radius: 50% !important;
    border: 2px solid #fcbfd6 !important;
  }

  /* Links */
  a {
    color: #cc6699 !important;
  }

  a:hover {
    color: #ff5e95 !important;
    text-decoration: underline !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #fff0f5;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #fcbfd6;
    border-radius: 8px;
  }
}
